#include <stdio.h>

int main() {
    int arr[5] = {10, 20, 30, 40, 50};
    int *p = arr;

    // 数组名等价于首元素指针
    printf("*(arr+0) = %d\n", *(arr+0));
    printf("*(p+0)   = %d\n", *(p+0));

    // 指针算术运算
    for (int i = 0; i < 5; i++) {
        printf("*(p+%d) = %d\n", i, *(p+i));
    }

    // 指向数组末尾的指针
    int *pend = arr + 5;
    printf("Total elements: %ld\n", pend - p);

    return 0;
}

